8	/**
9	 * Rejects a create-owner request whose email is already used by another owner, responding
10	 * 409. Runs after {@link NormalizeOwnerEmail} so the comparison is between lower-cased
11	 * values, and before {@link BuildOwner} persists a duplicate. Email is optional: an absent
12	 * or blank email skips the check.
13	 */
14	public class EnsureUniqueEmail {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateEmailException {
18	        String email = request.getEmail();
19	        if (email == null || email.isBlank()) {
20	            return;
21	        }
22	        if (!ownerRepository.findByEmail(email).isEmpty()) {
23	            throw new DuplicateEmailException(email);
24	        }
25	    }
26	}
