216	
217	    protected void setPetsInternal(Set<Pet> pets) {
218	        this.pets = pets;
219	    }
220	
221	    public List<Pet> getPets() {
222	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
223	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
224	        return Collections.unmodifiableList(sortedPets);
225	    }
226	
227	    public void setPets(List<Pet> pets) {
228	        this.pets = new HashSet<>(pets);
229	    }
230	
231	    public void addPet(Pet pet) {
232	        getPetsInternal().add(pet);
233	        pet.setOwner(this);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name) {
243	        return getPet(name, false);
244	    }
245	
246	    /**
247	     * Return the Pet with the given name, or null if none found for this Owner.
248	     *
249	     * @param name to test
250	     * @return true if pet name is already in use
251	     */
252	    public Pet getPet(String name, boolean ignoreNew) {
253	        name = name.toLowerCase();
254	        for (Pet pet : getPetsInternal()) {
255	            if (!ignoreNew || !pet.isNew()) {
256	                String compName = pet.getName();
257	                compName = compName.toLowerCase();
258	                if (compName.equals(name)) {
259	                    return pet;
260	                }
261	            }
262	        }
263	        return null;
264	    }
265	
266	    public Pet getPet(Integer petId) {
267	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
268	    }
269	
270	    @Override
271	    public String toString() {
272	        return new ToStringCreator(this)
273	
274	            .append("id", this.getId())
275	            .append("new", this.isNew())
276	            .append("lastName", this.getLastName())
277	            .append("firstName", this.getFirstName())
278	            .append("address", this.address)
279	            .append("city", this.city)
280	            .append("telephone", this.telephone)
281	            .toString();
282	    }
283	}
