1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.List;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.util.AddressNormalizer;
11	
12	/**
13	 * Shared household logic. An owner belongs to a household identified by their last name
14	 * and postal address. The last name is compared case-insensitively with collapsed
15	 * whitespace; the address is compared in its normalized form (see {@link AddressNormalizer})
16	 * so the same household resolves regardless of casing, spacing or street-type abbreviation.
17	 * The identifier is derived deterministically from those two fields, so every owner in the
18	 * same household resolves to the same stable value without any coordination.
19	 */
20	final class Households {
21	
22	    private Households() {
23	    }
24	
25	    /**
26	     * The existing owners that share a household (same last name and address) with the
27	     * given fields.
28	     */
29	    static List<Owner> membersOf(OwnerRepository ownerRepository, String lastName, String address) {
30	        String key = normalizeName(lastName);
31	        String addr = AddressNormalizer.normalize(address);
32	        return ownerRepository.findByLastName(lastName).stream()
33	                .filter(owner -> normalizeName(owner.getLastName()).equals(key)
34	                        && AddressNormalizer.normalize(owner.getAddress()).equals(addr))
35	                .toList();
36	    }
37	
38	    /**
39	     * The stable identifier shared by every owner at the given last name and address.
40	     */
41	    static String idFor(String lastName, String address) {
42	        return sha256Hex(normalizeName(lastName) + "|" + AddressNormalizer.normalize(address))
43	                .substring(0, 12).toUpperCase();
44	    }
45	
46	    private static String normalizeName(String value) {
47	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
48	    }
49	
50	    private static String sha256Hex(String value) {
51	        try {
52	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
53	            StringBuilder sb = new StringBuilder(digest.length * 2);
54	            for (byte b : digest) {
55	                sb.append(String.format("%02x", b));
56	            }
57	            return sb.toString();
58	        }
59	        catch (NoSuchAlgorithmException e) {
60	            throw new IllegalStateException("SHA-256 not available", e);
61	        }
62	    }
63	}
