1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Links owners who share a household. When a create-owner request opts in with
12	 * {@code sharesHousehold} true and an existing same-last-name, same-address owner is
13	 * present, assigns the shared, stable {@code householdId} (see {@link Households}) to both
14	 * the new owner and every existing household member. Runs after {@link BuildOwner} so the
15	 * new entity exists, and before {@link SaveOwner} persists it.
16	 */
17	public class AssignHouseholdId {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
20	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        List<Owner> members = Households.membersOf(ownerRepository, request.getLastName(), request.getAddress());
24	        if (members.isEmpty()) {
25	            return;
26	        }
27	        String householdId = Households.idFor(request.getLastName(), request.getAddress());
28	        owner.setHouseholdId(householdId);
29	        for (Owner member : members) {
30	            if (!householdId.equals(member.getHouseholdId())) {
31	                member.setHouseholdId(householdId);
32	                ownerRepository.save(member);
33	            }
34	        }
35	    }
36	}
